     1	import crypto from 'node:crypto';
     2	import { mkdir, readFile, rename, rm, stat, writeFile } from 'node:fs/promises';
     3	import path from 'node:path';
     4	
     5	// Review-surface violations are deliberately kept apart from review staleness.
     6	//
     7	// Stale means "the review no longer covers the current head" and is resolved by
     8	// re-running the review; the result artifact is overwritten and the previous
     9	// state is supposed to disappear. A violation means "the review surface moved
    10	// while the review was running", so what the reviewer actually inspected can no
    11	// longer be reconstructed. Re-running does not answer that question, therefore
    12	// the record must survive every later run.
    13	//
    14	// The separation is structural, not conventional: violations live in their own
    15	// story-level file, and this module exposes no delete or update operation. The
    16	// only write path appends under a story-level lock, and it is idempotent on a
    17	// deterministic violation_id so replaying the same close cannot inflate the
    18	// ledger either.
    19	//
    20	// The file itself is still just a file, and nothing here can stop someone from
    21	// overwriting it out of band. What the design does instead is make that visible:
    22	// review close also stamps surface_violation_id onto the lifecycle entry, and
    23	// reconciliation reports any pointer with no matching ledger entry as a
    24	// missing-entry violation. Replacing the ledger with a well-formed empty one
    25	// therefore trades a recorded violation for a different recorded violation.
    26	
    27	export const REVIEW_SURFACE_VIOLATIONS_FILE = 'surface-violations.json';
    28	export const REVIEW_SURFACE_MUTATION_KIND = 'review_surface_mutated_during_review';
    29	export const REVIEW_SURFACE_INTEGRITY_GATE_ID = 'gate:review_surface_integrity';
    30	
    31	const SCHEMA_VERSION = '0.1.0';
    32	
    33	export function getReviewSurfaceViolationsPath(storyReviewDir) {
    34	  return path.join(storyReviewDir, REVIEW_SURFACE_VIOLATIONS_FILE);
    35	}
    36	
    37	export const REVIEW_SURFACE_LEDGER_UNREADABLE = 'VIBEPRO_REVIEW_SURFACE_LEDGER_UNREADABLE';
    38	export const REVIEW_SURFACE_LEDGER_UNREADABLE_VIOLATION_ID = 'ledger_unreadable';
    39	export const REVIEW_SURFACE_POINTERS_UNREADABLE_VIOLATION_ID = 'lifecycle_pointers_unreadable';
    40	
    41	/**
    42	 * A malformed or structurally invalid ledger is rejected, never read as empty.
    43	 * Treating corrupt content as "no violations" would hand back the erase path
    44	 * this module exists to remove: truncating the file would silently clear every
    45	 * recorded violation. An absent file is different — nothing was ever recorded.
    46	 */
    47	export async function readReviewSurfaceViolations(storyReviewDir, storyId = null) {
    48	  const filePath = getReviewSurfaceViolationsPath(storyReviewDir);
    49	  let raw;
    50	  try {
    51	    raw = await readFile(filePath, 'utf8');
    52	  } catch (error) {
    53	    if (error.code === 'ENOENT') return { schema_version: SCHEMA_VERSION, story_id: storyId, entries: [] };
    54	    throw error;
    55	  }
    56	  let parsed;
    57	  try {
    58	    parsed = JSON.parse(raw);
    59	  } catch (error) {
    60	    throw unreadableLedgerError(filePath, `malformed JSON: ${error.message}`);
    61	  }
    62	  if (!Array.isArray(parsed?.entries)) {
    63	    throw unreadableLedgerError(filePath, 'invalid ledger: entries[] is missing or not an array');
    64	  }
    65	  return { schema_version: SCHEMA_VERSION, story_id: storyId, ...parsed, entries: parsed.entries };
    66	}
    67	
    68	function unreadableLedgerError(filePath, detail) {
    69	  const error = new Error(`review surface violation ledger ${filePath} is unreadable and is rejected rather than read as empty (${detail}). An unreadable ledger fails closed because clearing it would erase append-only violation records. Restore the file from a copy, or move it aside so a fresh ledger can be started - both review close and review record refuse to append over it until then. An accepted decision record on ${REVIEW_SURFACE_INTEGRITY_GATE_ID}:${REVIEW_SURFACE_LEDGER_UNREADABLE_VIOLATION_ID} clears the pr prepare gate but does not make this append succeed.`);
    70	  error.code = REVIEW_SURFACE_LEDGER_UNREADABLE;
    71	  error.ledger_path = filePath;
    72	  return error;
    73	}
    74	
    75	/**
    76	 * Compare the surface a review lifecycle started on with the surface observed at
    77	 * close time. Returns null when nothing moved, or when the close is not the kind
    78	 * of close that can carry a completed review.
    79	 */
    80	export function detectReviewSurfaceMutation(lifecycleEntry, {
    81	  closeHeadSha = null,
    82	  closeSurfaceDigest = null,
    83	  closeReason = null
    84	} = {}) {
    85	  if (!lifecycleEntry) return null;
    86	  // replaced / timeout / manual_shutdown closes never carry a review result
    87	  // (review record refuses to attach to them), so a moved surface there is a
    88	  // discarded attempt, not a contaminated verdict.
    89	  if (closeReason !== 'completed') return null;
    90	  const startHeadSha = normalize(lifecycleEntry.head_sha);
    91	  const startSurfaceDigest = normalize(lifecycleEntry.surface_digest);
    92	  const changedFields = [];
    93	  if (startHeadSha && closeHeadSha && startHeadSha !== closeHeadSha) changedFields.push('head_sha');
    94	  if (startSurfaceDigest && closeSurfaceDigest && startSurfaceDigest !== closeSurfaceDigest) {
    95	    changedFields.push('surface_digest');
    96	  }
    97	  if (changedFields.length === 0) return null;
    98	  return {
    99	    kind: REVIEW_SURFACE_MUTATION_KIND,
   100	    evidence_class: 'violation',
   101	    changed_fields: changedFields,
   102	    started: { head_sha: startHeadSha, surface_digest: startSurfaceDigest },
   103	    closed: { head_sha: normalize(closeHeadSha), surface_digest: normalize(closeSurfaceDigest) }
   104	  };
   105	}
   106	
   107	export function buildReviewSurfaceViolationId(violation) {
   108	  const material = [
   109	    violation.story_id,
   110	    violation.stage,
   111	    violation.role,
   112	    violation.lifecycle_id,
   113	    violation.kind,
   114	    violation.started?.head_sha,
   115	    violation.started?.surface_digest,
   116	    violation.closed?.head_sha,
   117	    violation.closed?.surface_digest
   118	  ].map((value) => value ?? '').join('|');
   119	  return `rsv-${crypto.createHash('sha256').update(material).digest('hex').slice(0, 16)}`;
   120	}
   121	
   122	/**
   123	 * Append-only. Never removes or rewrites an existing entry: a replayed close
   124	 * resolves to the same violation_id and returns the entry already on disk.
   125	 *
   126	 * The whole read-modify-write is serialised on a story-level lock. Without it,
   127	 * two concurrent closes both read the same entries[] and the second rename drops
   128	 * the first entry — an erasure by race, on the one file that must never lose a
   129	 * record. Deduplicating on violation_id does not help here: it collapses
   130	 * identical facts, it does not serialise distinct ones.
   131	 */
   132	export async function appendReviewSurfaceViolation(storyReviewDir, storyId, violation) {
   133	  await mkdir(storyReviewDir, { recursive: true });
   134	  return withDirectoryLock(path.join(storyReviewDir, LEDGER_LOCK_DIR), async () => {
   135	    const existing = await readReviewSurfaceViolations(storyReviewDir, storyId);
   136	    const entry = {
   137	      schema_version: SCHEMA_VERSION,
   138	      violation_id: buildReviewSurfaceViolationId({ ...violation, story_id: storyId }),
   139	      story_id: storyId,
   140	      ...violation,
   141	      detected_by: violation.detected_by ?? 'review close',
   142	      recorded_at: violation.recorded_at ?? new Date().toISOString()
   143	    };
   144	    const already = existing.entries.find((item) => item.violation_id === entry.violation_id);
   145	    if (already) return { entry: already, appended: false, entries: existing.entries };
   146	    const entries = [...existing.entries, entry];
   147	    await writeViolations(storyReviewDir, storyId, entries);
   148	    return { entry, appended: true, entries };
   149	  });
   150	}
   151	
   152	const LEDGER_LOCK_DIR = '.surface-violations.lock';
   153	const LOCK_STALE_MS = 30_000;
   154	
   155	async function withDirectoryLock(lockDir, callback) {
   156	  const start = Date.now();
   157	  while (true) {
   158	    try {
   159	      await mkdir(lockDir);
   160	      break;
   161	    } catch (error) {
   162	      if (error.code !== 'EEXIST') throw error;
   163	      const lockStat = await stat(lockDir).catch((statError) => {
   164	        if (statError.code === 'ENOENT') return null;
   165	        throw statError;
   166	      });
   167	      if (lockStat && Date.now() - lockStat.mtimeMs > LOCK_STALE_MS) {
   168	        await rm(lockDir, { recursive: true, force: true });
   169	        continue;
   170	      }
   171	      if (Date.now() - start > LOCK_STALE_MS) {
   172	        throw new Error(`timed out waiting for the review surface violation ledger lock: ${lockDir}`);
   173	      }
   174	      await new Promise((resolve) => setTimeout(resolve, 25));
   175	    }
   176	  }
   177	  try {
   178	    return await callback();
   179	  } finally {
   180	    await rm(lockDir, { recursive: true, force: true });
   181	  }
   182	}
   183	
   184	/**
   185	 * The ledger is not the only record that a violation happened: review close also
   186	 * stamps surface_violation_id onto the lifecycle entry. Reconciling the two
   187	 * closes the erase path that corruption-rejection alone leaves open — replacing
   188	 * the ledger with a well-formed `{"entries": []}` is not malformed, but it
   189	 * orphans every lifecycle pointer, and an orphaned pointer is reported as a
   190	 * missing-entry violation that fails closed exactly like the record it replaced.
   191	 */
   192	export function reconcileReviewSurfaceViolationPointers(entries = [], lifecycleEntries = []) {
   193	  const known = new Set((Array.isArray(entries) ? entries : []).map((entry) => entry.violation_id));
   194	  const orphans = new Map();
   195	  for (const lifecycle of Array.isArray(lifecycleEntries) ? lifecycleEntries : []) {
   196	    for (const violationId of lifecycleViolationPointers(lifecycle)) {
   197	    if (!violationId || known.has(violationId) || orphans.has(violationId)) continue;
   198	    orphans.set(violationId, {
   199	      // Deliberately NOT the erased entry's own id. Reusing it would let the
   200	      // decision record that acknowledged the original violation also acknowledge
   201	      // its disappearance, so an already-acknowledged violation could be deleted
   202	      // with nothing left blocking. Erasing a record is a separate fact and needs
   203	      // a separate human acknowledgement.
   204	      violation_id: `missing:${violationId}`,
   205	      erased_violation_id: violationId,
   206	      kind: REVIEW_SURFACE_LEDGER_ENTRY_MISSING_KIND,
   207	      evidence_class: 'violation',
   208	      changed_fields: [],
   209	      stage: lifecycle.stage ?? null,
   210	      role: lifecycle.role ?? null,
   211	      lifecycle_id: lifecycle.lifecycle_id ?? null,
   212	      detected_by: 'ledger reconciliation',
   213	      detail: `Lifecycle ${lifecycle.lifecycle_id ?? 'unknown'} records surface_violation_id ${violationId}, but no such entry exists in the ledger. The ledger has been replaced or edited; append-only records cannot disappear.`
   214	    });
   215	    }
   216	  }
   217	  return [...orphans.values()];
   218	}
   219	
   220	// One lifecycle can carry more than one violation: an orphaned close records one
   221	// and the record that completes the same entry can record another. Reading only
   222	// the latest pointer would make the earlier erasure invisible.
   223	function lifecycleViolationPointers(lifecycle) {
   224	  const pointers = Array.isArray(lifecycle?.surface_violation_ids) ? lifecycle.surface_violation_ids : [];
   225	  const latest = lifecycle?.surface_violation_id;
   226	  return latest && !pointers.includes(latest) ? [...pointers, latest] : pointers;
   227	}
   228	
   229	export const REVIEW_SURFACE_LEDGER_ENTRY_MISSING_KIND = 'review_surface_violation_entry_missing';
   230	
   231	/**
   232	 * Acknowledgement never deletes anything. It pairs surviving ledger entries with
   233	 * accepted decision records so a human episode can close the gate while the
   234	 * recorded fact stays in the artifact forever.
   235	 */
   236	export function summarizeReviewSurfaceViolations(entries = [], {
   237	  decisionRecords = null,
   238	  lifecycleEntries = [],
   239	  pointersReadable = true
   240	} = {}) {
   241	  // Lifecycles closed before this detection existed carry no surface_detection.
   242	  // They are not "checked and clean", and the summary must not let them be
   243	  // reported as such.
   244	  const lifecycles = Array.isArray(lifecycleEntries) ? lifecycleEntries : [];
   245	  const closedLifecycles = lifecycles.filter((item) => item?.closed_at || ['closed', 'replaced'].includes(item?.status));
   246	  const unevaluated = closedLifecycles.filter((item) => item?.surface_detection !== 'evaluated');
   247	  const accepted = (decisionRecords?.decisions ?? [])
   248	    .filter((decision) => decision?.status === 'accepted' && typeof decision.source === 'string');
   249	  const reconciled = [
   250	    ...(Array.isArray(entries) ? entries : []),
   251	    ...reconcileReviewSurfaceViolationPointers(entries, lifecycleEntries),
   252	    ...(pointersReadable ? [] : [{
   253	      violation_id: REVIEW_SURFACE_POINTERS_UNREADABLE_VIOLATION_ID,
   254	      kind: 'review_surface_lifecycle_pointers_unreadable',
   255	      evidence_class: 'violation',
   256	      changed_fields: [],
   257	      detected_by: 'ledger reconciliation',
   258	      detail: 'The lifecycle entries carrying surface_violation_id could not be read, so the ledger cross-check did not run. In this state a ledger rewrite would not be detected, which is why it blocks rather than reading the missing pointers as agreement.'
   259	    }])
   260	  ];
   261	  const items = reconciled.map((entry) => {
   262	    const acknowledgement = accepted.find((decision) => decision.source === `${REVIEW_SURFACE_INTEGRITY_GATE_ID}:${entry.violation_id}`) ?? null;
   263	    return {
   264	      ...entry,
   265	      acknowledged: Boolean(acknowledgement),
   266	      acknowledgement: acknowledgement ? {
   267	        decision_id: acknowledgement.decision_id ?? null,
   268	        source: acknowledgement.source,
   269	        reason: acknowledgement.reason ?? null,
   270	        artifact: acknowledgement.artifact ?? null,
   271	        reviewer: acknowledgement.reviewer ?? null
   272	      } : null
   273	    };
   274	  });
   275	  const unacknowledged = items.filter((item) => !item.acknowledged);
   276	  return {
   277	    schema_version: SCHEMA_VERSION,
   278	    readable: true,
   279	    evaluated_lifecycle_count: closedLifecycles.length - unevaluated.length,
   280	    unevaluated_lifecycle_count: unevaluated.length,
   281	    total_count: items.length,
   282	    acknowledged_count: items.length - unacknowledged.length,
   283	    unacknowledged_count: unacknowledged.length,
   284	    entries: items,
   285	    unacknowledged
   286	  };
   287	}
   288	
   289	/**
   290	 * The blocking summary for a ledger that could not be read. It reports the
   291	 * unreadable state as a violation entry so the gate fails closed: an unreadable
   292	 * ledger cannot be distinguished from an erased one, and both must stop the PR.
   293	 *
   294	 * It runs through the same acknowledgement path as any other violation. There is
   295	 * no self-service repair — .vibepro artifacts are not tracked in git, so
   296	 * "restore the file" is not a recovery for most repositories — and a block with
   297	 * no exit is not a gate, it is a dead end.
   298	 */
   299	export function buildUnreadableReviewSurfaceViolationSummary(error, { decisionRecords = null } = {}) {
   300	  const summary = summarizeReviewSurfaceViolations([{
   301	    violation_id: REVIEW_SURFACE_LEDGER_UNREADABLE_VIOLATION_ID,
   302	    kind: 'review_surface_ledger_unreadable',
   303	    evidence_class: 'violation',
   304	    changed_fields: [],
   305	    detected_by: 'ledger read',
   306	    detail: error?.message ?? 'review surface violation ledger could not be read'
   307	  }], { decisionRecords });
   308	  return {
   309	    ...summary,
   310	    readable: false,
   311	    unreadable_reason: error?.message ?? 'review surface violation ledger could not be read'
   312	  };
   313	}
   314	
   315	export function buildReviewSurfaceViolationAcknowledgementCommand(storyId, violationId) {
   316	  return `vibepro decision record . --id ${storyId} --type needs_review --source ${REVIEW_SURFACE_INTEGRITY_GATE_ID}:${violationId} --status accepted --summary "<what the reviewer actually inspected>" --reason "<human judgement on the mid-review surface change>" --artifact <evidence-path>`;
   317	}
   318	
   319	async function writeViolations(storyReviewDir, storyId, entries) {
   320	  await mkdir(storyReviewDir, { recursive: true });
   321	  const filePath = getReviewSurfaceViolationsPath(storyReviewDir);
   322	  const tempPath = `${filePath}.${crypto.randomUUID()}.tmp`;
   323	  const payload = {
   324	    schema_version: SCHEMA_VERSION,
   325	    model: 'vibepro-review-surface-violations-v1',
   326	    story_id: storyId,
   327	    append_only: true,
   328	    updated_at: new Date().toISOString(),
   329	    entries
   330	  };
   331	  try {
   332	    await writeFile(tempPath, `${JSON.stringify(payload, null, 2)}\n`);
   333	    await rename(tempPath, filePath);
   334	  } catch (error) {
   335	    await rm(tempPath, { force: true });
   336	    throw error;
   337	  }
   338	}
   339	
   340	function normalize(value) {
   341	  const text = typeof value === 'string' ? value.trim() : '';
   342	  return text.length > 0 ? text : null;
   343	}

